  function execution(){if(state.task?.stopped)return `<details class="execution"><summary>${icon('stop')}任务已停止<span class="grow"></span><span class="muted">可重新生成</span></summary><div class="steps caption">已中止本地演示计时器，没有调用模型或外部工具。</div></details>`;return `<details class="execution" ${state.busy?'open':''}><summary>${state.busy?'<span class="spinner"></span>':icon('check')}<span>${state.busy?'正在研究，整理证据与结论':'已完成研究'}</span><span class="grow"></span><span class="muted">${state.busy?'执行中':'4 个步骤'}</span>${icon('down','chevron')}</summary><div class="steps">${[['拆解研究问题','明确对比维度，建立资料清单','brain'],['检索与交叉核验','网页检索 / 网页读取 / 3 份演示资料','search'],['数据分析与可视化','数据分析师 / 表格和图表','chart'],['整理研究报告','HTML 分析报告及来源链接','file']].map(([a,b,c],i)=>`<div class="execution-step">${icon(state.busy&&i===3?'clock':'check',state.busy&&i===3?'warning':'success')}<div><span>${a}</span><p>${b}</p></div></div>`).join('')}</div></details>`;}
  function researchBody(){if(state.task?.stopped)return `<p class="soft">任务已停止。你可以调整问题后重新发送，或继续体验演示。</p>${button('重新生成','regenerate','refresh')}`;const sales=state.task?.kind==='sales';return `<h2>${sales?'第三季度销售数据分析':'AI 编程工具竞品调研'}</h2><p>已按${sales?'月度收入、产品结构与增长变化':'使用场景、核心能力、工作流与使用门槛'}整理演示报告。以下内容用于确认界面的阅读与交互效果。</p><p>${sales?'示例数据覆盖 7–9 月，整体收入呈上升趋势。可以在右侧交互图表中切换查看月度变化。':'对比工具时，应同时考虑上下文获取、工具执行、结果验证与交付能力，而不只比较模型的单轮回答。'}<button class="citation" data-action="sources" aria-label="查看来源 1">1</button><button class="citation" data-action="sources" aria-label="查看来源 2">2</button></p><ul><li><strong>${sales?'收入趋势':'核心能力'}</strong>：${sales?'月度收入从 12.8 万元增长至 18.6 万元。':'按代码理解、编辑、执行和验证拆分对比维度。'}</li><li><strong>${sales?'产品结构':'适用场景'}</strong>：${sales?'标准版贡献主要收入，专业版占比持续增加。':'区分日常补全、仓库级修改与长任务协作。'}</li><li><strong>${sales?'后续建议':'证据要求'}</strong>：${sales?'结合订单量、客单价和退款率进一步核验增长质量。':'为关键结论保留来源与核验日期。'}</li></ul><button type="button" class="file-artifact" data-action="open-report">${icon('file')}<span><strong>${sales?'第三季度销售分析':'AI 编程工具竞品调研'}.html</strong><small>HTML 报告 / 可交互图表 / 演示文件</small></span><span class="grow"></span><span class="text-link">打开预览</span>${icon('right')}</button><p class="caption">原型说明：上述数据及结论均为演示，不代表真实模型输出或调研事实。</p><div class="message-actions">${ib('copy','复制回答','copy-answer')}${ib('like','有帮助','feedback')}${ib('refresh','重新生成','regenerate')}</div>`;}
  function chat(){return `<section class="page"><div class="chat-layout"><div class="conversation"><header class="chat-header"><span class="chat-title">${E(taskTitle())}</span><div class="header-actions">${button('工作区','open-report','panel',state.workspace?'active':'')}${ib('star','收藏对话','favorite-chat')}${ib('settings','原型导航与显示','guide')}</div></header><div class="messages" id="message-scroll"><div class="message-column">${historyMessages()}<div class="user-message">${E(state.task?.query||taskTitle())}</div><article class="agent-message"><div class="agent-sign">${icon('spark')}<span>Research Agent</span><span class="grow"></span><span class="muted">${E(state.model)}</span></div>${execution()}<div id="answer-body">${state.busy?'<p class="soft">正在整理研究结果…</p>':researchBody()}</div></article></div></div><div class="chat-composer-area">${composer()}<p class="demo-note">交互原型，回答与执行步骤均为本地演示</p></div></div>${state.workspace?workspace():''}</div></section>`;}
  function workspace(){return `<aside class="workspace-pane" aria-label="右侧工作区" ${state.workspaceWidth?`style="width:${state.workspaceWidth}px"`:''}><button class="resize-handle" id="resize-handle" role="separator" aria-label="调整工作区宽度" aria-orientation="vertical" aria-valuemin="310" aria-valuemax="900" aria-valuenow="${state.workspaceWidth||480}"></button><div class="workspace-header">${icon('code')}<span>${state.workspaceTab==='sources'?'证据与来源':'index.html'}</span><span class="grow"></span>${ib('download','下载报告','download-report')}${ib('close','关闭工作区','close-workspace')}</div><div class="workspace-toolbar"><button class="${state.workspaceTab==='preview'?'active':''}" data-action="workspace-tab" data-tab="preview">预览</button><button class="${state.workspaceTab==='code'?'active':''}" data-action="workspace-tab" data-tab="code">代码</button><button class="${state.workspaceTab==='sources'?'active':''}" data-action="workspace-tab" data-tab="sources">来源 <span class="tag">3</span></button><span class="grow"></span><span class="muted">演示报告</span></div>${state.workspaceTab==='preview'?'<iframe class="report-frame" id="report-frame" title="HTML 分析报告预览" sandbox="allow-scripts"></iframe>':state.workspaceTab==='code'?`<pre class="code-view">${E(reportHTML())}</pre>`:`<div class="source-list">${['产品官方文档摘要','公开功能对照表','社区反馈整理'].map((s,i)=>`<div class="source-item"><span class="tag">${i+1}</span><strong>${s}</strong><p>示例证据，用于演示来源查看与交叉核验。</p><button class="text-link" data-action="read-source" data-index="${i}">查看原文摘要</button></div>`).join('')}<p class="demo-note">来源为虚构演示条目，不会访问外部网站。</p></div>`}</aside>`;}
  function reportHTML(){return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><style>*{box-sizing:border-box}body{margin:0;background:#f6f8f8;color:#203e49;font:13px/1.8 'Segoe UI','Microsoft YaHei UI',sans-serif}main{padding:32px 30px;max-width:1000px;margin:auto}small{color:#6d8791;font-size:10px}h1{font-size:26px;line-height:1.4;font-weight:550;letter-spacing:-1px;margin:14px 0}h2{font-size:15px;margin:26px 0 12px}p{color:#56727e}header{border-bottom:1px solid #d3e1e5;padding-bottom:22px}.stats{display:flex;gap:26px;margin:23px 0}.stats strong{display:block;font-size:24px;font-weight:500}.stats span{font-size:10px;color:#69818b}select{border:1px solid #ccdfe3;background:#fff;border-radius:6px;padding:5px 10px;color:#294f5e;font-size:11px}.bars{height:170px;display:flex;align-items:flex-end;gap:18px;padding:15px 18px 25px;border-bottom:1px solid #cadde1}.column{flex:1;background:#68a8b6;position:relative;border-radius:4px 4px 0 0;transition:height .25s}.column:nth-child(2){background:#3b7f93}.column:nth-child(3){background:#1e586f}.column span{position:absolute;bottom:-23px;left:0;right:0;text-align:center;font-size:10px;color:#63818d}.column i{position:absolute;top:-22px;left:0;right:0;text-align:center;font-style:normal;font-size:10px;color:#375f70}table{border-collapse:collapse;width:100%;font-size:11px}th,td{padding:10px 4px;text-align:left;border-bottom:1px solid #d5e2e5}th{font-weight:500;color:#62818f}.note{font-size:10px;padding:13px;background:#e6f0f2;border-radius:7px;margin-top:26px}footer{border-top:1px solid #d1e1e6;margin-top:28px;padding-top:15px;font-size:10px;color:#75909b}</style></head><body><main><header><small>Research Agent / 分析报告</small><h1>${E(state.task?.kind==='sales'?'第三季度销售数据分析':'AI 编程工具竞品调研')}</h1><p>从资料到判断：让结论、数据与证据保持关联。</p><small>演示报告　2026 年 10 月</small></header><div class="stats"><div><strong id="metric">47.6 万</strong><span id="metric-label">季度收入（示例）</span></div><div><strong>20.7%</strong><span>平均环比增长（示例）</span></div><div><strong>3</strong><span>分析维度</span></div></div><h2>月度变化 <select id="chart-type" aria-label="图表指标"><option value="revenue">收入</option><option value="orders">订单量</option></select></h2><div class="bars"><div class="column" style="height:61%"><i>12.8 万</i><span>7 月</span></div><div class="column" style="height:77%"><i>16.2 万</i><span>8 月</span></div><div class="column" style="height:89%"><i>18.6 万</i><span>9 月</span></div></div><h2>关键对比</h2><table><thead><tr><th>分析维度</th><th>关注内容</th><th>交付形式</th></tr></thead><tbody><tr><td>数据趋势</td><td>收入、订单与结构变化</td><td>统计表与图表</td></tr><tr><td>研究证据</td><td>来源与交叉核验</td><td>参考资料清单</td></tr><tr><td>后续行动</td><td>验证假设与补充数据</td><td>可执行建议</td></tr></tbody></table><div class="note">本页面为交互原型的虚构示例，可切换图表指标。未调用真实模型，数据不可用于业务决策。</div><footer>研究报告的内容保持独立样式；深海材质仅应用于工作区外壳。</footer></main><script>document.getElementById('chart-type').onchange=function(){const revenue=this.value==='revenue';document.querySelectorAll('.column').forEach((el,i)=>{el.style.height=(revenue?[61,77,89]:[69,81,86])[i]+'%';el.querySelector('i').textContent=(revenue?['12.8 万','16.2 万','18.6 万']:['640','810','930'])[i]});document.getElementById('metric').textContent=revenue?'47.6 万':'2,380';document.getElementById('metric-label').textContent=revenue?'季度收入（示例）':'季度订单（示例）';};<\/script></body></html>`;}

function usageRows(){return state.usagePeriod==='近 7 天'?[['qwen-plus',79,'864,000','276,000','4.56'],['gpt-6.1-sol',36,'391,000','124,000','7.12'],['qwen-max',13,'144,000','41,000','1.00']]:[['qwen-plus',312,'3,240,000','1,044,000','16.72'],['gpt-6.1-sol',138,'1,464,000','476,000','25.90'],['qwen-max',46,'556,000','140,000','3.70']];}
function historyMessages(){return state.turns.map(turn=>`<div class="user-message" style="margin-top:30px">${E(turn.query)}</div><article class="agent-message"><div class="agent-sign">${icon('spark')}Research Agent</div>${turn.body}</article>`).join('');}
function mrag(){const kb=selectedKB();return `<section class="page">${header('MRAG 智能问答工作台','在选定知识源中检索文件与网页资料，回答、证据和调试数据保持可追溯。','database',button('历史','kb-history','clock','hide-mobile')+button('知识源','kb-toggle','database',state.kbOpen?'active':'')+button('证据','kb-evidence','book'))}<div class="mrag-body">${state.kbOpen?`<aside class="knowledge-pane" aria-label="知识源"><div class="panel-head"><h3>知识源</h3><span class="grow"></span>${ib('plus','创建知识库','new-kb')}${ib('close','收起知识源','kb-toggle')}</div><div class="kb-list"><select aria-label="选择知识库" data-change="kb">${knowledgeBases.map(k=>`<option value="${k.id}" ${kb?.id===k.id?'selected':''}>${E(k.name)}</option>`).join('')}${!knowledgeBases.length?'<option value="">还没有知识库</option>':''}</select>${kb?`<div class="section-title" style="margin:18px 0 10px"><span class="caption">${kb.files.length} 个资料源</span>${ib('trash','删除知识库','delete-kb')}</div><div class="kb-tools">${button('上传文件','kb-upload','upload')}<div class="inline-url"><input type="url" id="kb-url" aria-label="网页链接" placeholder="粘贴网页链接">${button('添加','kb-add-url','link','', 'aria-label="添加网页"')}</div></div>${kb.files.map((f,i)=>`<div class="document-item">${icon(f.type==='网页'?'globe':'file')}<div><strong>${E(f.name)}</strong><small>${E(f.type)} / ${f.chunks} 个切片</small><span class="status success">已就绪（演示）</span><button class="text-link" data-action="kb-document" data-index="${i}" style="display:block">查看正文</button></div>${ib('trash','移除资料','kb-remove-file',`data-index="${i}"`)}</div>`).join('')||'<p class="caption" style="padding:20px 0">上传文件或添加网页链接，开始整理资料。</p>'}`:'<p class="caption" style="padding:25px 0">创建一个知识库来开始管理文件。</p>'}</div><div class="panel-body" style="padding:12px"><p class="demo-note">资料操作仅保存在本原型中。</p></div></aside>`:''}<div class="mrag-chat"><div class="mrag-answer">${state.kbAnswer?`<div class="mrag-query"><div class="user-message">${E(state.query)}</div><article class="agent-message"><div class="agent-sign">${icon('spark')}Research Agent<span class="grow"></span><span class="tag">基于 ${E(kb?.name||'资料')}</span></div><h2>${E(kb?.id===1?'Java 是什么？':'资料要点整理')}</h2><p>${kb?.id===1?'Java 是一种通用编程语言，也指由开发工具、运行环境和标准库组成的软件平台。开发者可以编写源代码，编译为字节码，再通过 Java 虚拟机运行。':'已根据所选演示知识库整理核心要点，并为结论关联原文位置。实际检索与模型生成将在正式项目中完成。'}<button class="citation" data-action="kb-document" data-index="0">1</button></p><div class="source-block"><strong>${E(kb?.files[0]?.name||'示例文档')}</strong><p>“将知识、来源与研究过程保存在同一个可追溯的工作区。”</p><small class="muted">演示摘录 / 第 1 页 / 切片 001</small></div><p class="caption">当前为原型答案，未调用 Embedding、Qdrant 或语言模型。</p></article></div>`:`<div class="empty-state" style="height:100%">${icon('database')}<h2>${kb?'从一个问题开始':'先选择一个知识源'}</h2><p>${kb?`已选择「${E(kb.name)}」。从 ${kb.files.length} 份资料中寻找答案，并查看原文依据。`:'创建或选择知识库，再上传文件与网页资料。'}</p>${kb?button(kb.id===1?'什么是 Java？':'整理这份资料的关键结论','kb-suggestion','search'):button('创建知识库','new-kb','plus')}</div>`}</div><div class="mrag-bottom">${composer('kb-input',true)}</div></div></div></section>`;}
function artwork(i=0){const n=i%3;const palettes=[['#b9d7df','#1d667e','#12394e','#85bcc6'],['#e1d9cf','#a1b4af','#385c60','#f3e8d6'],['#c7d8e2','#748b98','#243e50','#d4d9d3']];const [sky,sea,deep,light]=palettes[n];return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 600" role="img" aria-label="${['静谧海岸与现代建筑','林间玻璃温室','海雾中的山脉'][n]}，原型矢量示意图"><defs><linearGradient id="sky${i}" x2="0" y2="1"><stop stop-color="${sky}"/><stop offset="1" stop-color="${light}"/></linearGradient><linearGradient id="sea${i}" x2=".7" y2="1"><stop stop-color="${sea}"/><stop offset="1" stop-color="${deep}"/></linearGradient><filter id="soft${i}"><feGaussianBlur stdDeviation="22"/></filter></defs><path fill="url(#sky${i})" d="M0 0h800v600H0z"/><ellipse cx="${n===1?540:550}" cy="125" rx="110" ry="65" fill="${light}" opacity=".5" filter="url(#soft${i})"/>${n===0?`<path d="M0 270Q200 300 330 260T800 280V600H0" fill="url(#sea${i})"/><path d="M0 430Q220 370 430 440T800 450v150H0" fill="${deep}" opacity=".25"/><path d="M80 350 360 275 520 320 240 403z" fill="#c5d4d0"/><path d="M145 310 145 220 365 165 365 257z" fill="#e5e8dc"/><path d="m365 165 122 51v91l-122-50z" fill="#a4bab7"/><path d="m145 220 220-55 122 51-220 58z" fill="#f0eee4"/><path d="M174 237 331 197v52l-157 41z" fill="#315e69"/><path d="m384 206 83 33v45l-83-34z" fill="#426b70"/><path d="M0 540q180-80 350-20t450 20" fill="none" stroke="#c9e2e0" stroke-width="2" opacity=".3"/>`:n===1?`<path d="M0 240Q200 180 400 250T800 230V600H0z" fill="#758e85"/><path d="M0 390q200-190 450-80t350-10v300H0" fill="#426961"/><g opacity=".6" stroke="#233f39" stroke-width="15"><path d="M75 410V85 M695 350V50 M595 335V100 M185 330V140"/></g><path d="M230 400V260l170-85 170 85v140z" fill="#b4d8cb" opacity=".8"/><path d="m230 260 170-85 170 85 M400 175v225 M230 260h340 M315 218v182 M485 218v182 M230 330h340" fill="none" stroke="#e2e9db" stroke-width="5"/><path d="m230 400 170-40 170 40-170 75z" fill="#d5cfb5"/><path d="M0 520q200-60 400-45t400 40v85H0" fill="#264c43"/>`:`<path d="m0 400 140-190 140 130 180-200 180 160 160-80v380H0" fill="#8ca5af"/><path d="m0 490 190-200 210 140 170-170 230 160v180H0" fill="#5c7e8d"/><path d="m0 500 260-130 220 160 150-110 170 85v95H0" fill="url(#sea${i})"/><ellipse cx="310" cy="370" rx="440" ry="55" fill="${light}" opacity=".44" filter="url(#soft${i})"/><path d="M0 560q400-40 800-10v50H0" fill="#aec5ce" opacity=".3"/>`}<rect x="0" y="0" width="800" height="600" fill="none" stroke="${light}" stroke-opacity=".12" stroke-width="4"/></svg>`;}
function images(){return `<section class="page">${header('图片','描述画面，生成图片，或基于参考图继续创作。','image',ib('settings','生图设置','image-settings'))}<div class="content-scroll"><div class="image-workspace"><div class="glass-panel image-prompt"><label for="image-prompt" class="visually-hidden">描述新图片</label><textarea id="image-prompt" placeholder="描述新图片，例如：海边的现代建筑，清晨，胶片质感…">${E(state.imagePrompt)}</textarea><div class="image-options">${button('参考图','image-attach','plus','subtle')}<select aria-label="图片比例" id="image-ratio"><option>4:3</option><option>1:1</option><option>16:9</option><option>9:16</option></select><select aria-label="图片风格" id="image-style"><option>自然</option><option>摄影</option><option>建筑</option><option>插画</option></select><span class="grow"></span>${button('生成图片','generate-image','up','primary')}</div></div><div class="section-title"><div class="segmented">${['探索','我的作品'].map(t=>`<button class="${state.imageTab===t?'active':''}" data-action="image-tab" data-tab="${t}">${t}</button>`).join('')}</div><span class="caption">${state.imageTab==='探索'?'创作示例':'本次原型中生成的作品'}</span></div><div class="gallery">${Array.from({length:state.imageTab==='探索'?state.imageCount:Math.max(0,state.imageCount-3)},(_,j)=>{const i=state.imageTab==='探索'?j:j+3;const record=state.imageRecords.find(r=>r.index===i);return `<article class="art-card"><button type="button" class="artwork" style="aspect-ratio:${E((record?.ratio||'4:3').replace(':','/'))}" data-action="preview-image" data-index="${i}">${artwork(i)}</button><div class="art-caption"><div><strong>${E(i>2?(record?.prompt||'新的创作示例'):['静谧海岸','林间温室','远山与海雾'][i%3])}</strong><p>${i>2?'本地演示生成':'矢量示意图'} / ${E(record?.ratio||'4:3')}</p></div>${ib('more','图片操作','image-menu',`data-index="${i}"`)}</div></article>`;}).join('')||'<div class="no-results">还没有作品。输入画面描述，体验生成流程。</div>'}</div><p class="demo-note">图片为内置矢量示意图。生成和编辑仅演示交互，不调用付费图像服务。</p></div></div></section>`;}
function modelPage(){const m=models.find(x=>x.id===state.selectedModel)||models[0];return `<section class="page">${header('模型配置','接入用于 Agent 推理的大语言模型，支持 OpenAI 兼容 Chat Completions。','cpu',ib('refresh','刷新模型','refresh-models')+button('新增模型','new-model','plus','primary'))}<div class="content-scroll"><div class="split-editor"><aside class="list-pane"><input type="search" placeholder="搜索模型名 / Base URL" aria-label="搜索模型" data-filter="model-list"><div class="segmented" style="margin-top:13px"><button class="active" data-action="model-filter" data-filter-value="">全部</button><button data-action="model-filter" data-filter-value="阿里云">阿里云</button><button data-action="model-filter" data-filter-value="兼容">自定义</button></div>${['阿里云百炼','OpenAI 兼容'].map(provider=>`<div class="list-section"><h3>${provider}</h3>${models.filter(x=>x.provider===provider).map(x=>`<button class="selectable-row ${m?.id===x.id?'active':''}" data-searchable="model-list" data-action="select-model" data-id="${x.id}"><span class="row-icon">${icon('cpu')}</span><span><strong>${E(x.name)}</strong><small>${E(x.provider)}</small><span class="status ${x.enabled?'success':'muted'}" style="display:flex;margin-top:4px">${x.enabled?'已启用':'已停用'}</span></span></button>`).join('')}</div>`).join('')}</aside>${m?`<form class="glass-panel editor-pane" data-form="model"><div class="panel-head">${icon('cpu')}<h3>${E(m.name)}</h3><span class="grow"></span><span class="caption">已启用</span>${toggle(m.enabled,'toggle-model',`data-id="${m.id}" aria-label="启用模型"`)}</div><div class="panel-body"><p class="editor-section-title">服务商</p><div class="field-grid">${choose('服务商预设','provider',['阿里云百炼','OpenAI 兼容'],m.provider)}${input('模型类型','type','openai','text','决定请求体适配方式')}</div>${input('Base URL','url',m.url,'url','原型不发起网络请求。地址仅用于演示配置界面。','required')}<hr class="editor-divider"><p class="editor-section-title">模型与凭据</p><div class="field-grid">${input('模型标识（上游 model）','name',m.name,'text','','required')}${input('模型 ID（业务主键）','modelId',m.name,'text','创建后不可修改','readonly')}</div>${input('API Key','key','','password','原型不保存、不发送任何凭据。请勿填写真实密钥。','placeholder="填写演示值即可" autocomplete="off"')}<div class="field-grid">${input('Completions 路径','completions','/chat/completions')}${input('Embeddings 路径','embeddings','/embeddings')}</div><hr class="editor-divider"><p class="editor-section-title">能力与路由</p><div class="field-grid">${input('上下文窗口（token）','context',m.context,'number')}${choose('推理级别','reasoning',['medium','low','high'],'medium')}</div><p id="connection-result" class="caption" role="status"></p></div><footer class="form-footer">${button('测试连接','test-model','play')}<span class="grow"></span>${button('放弃改动','refresh-models','','subtle')}<button type="submit" class="button primary">保存修改</button></footer></form>`:'<div class="empty-state">请先添加模型。</div>'}</div></div></section>`;}
function agentsPage(){const a=agents.find(x=>x.id===state.selectedAgent)||agents[0];return `<section class="page">${header('子 Agent','配置专注于不同任务的子 Agent，由主 Agent 按需委派。','bot',button('新增子 Agent','new-agent','plus','primary'))}<div class="content-scroll"><div class="split-editor"><aside class="list-pane"><input type="search" placeholder="搜索子 Agent" aria-label="搜索子 Agent" data-filter="agent-list"><div class="list-section">${agents.map(x=>`<button class="selectable-row ${a?.id===x.id?'active':''}" data-searchable="agent-list" data-action="select-agent" data-id="${x.id}"><span class="row-icon">${icon('bot')}</span><span><strong>${E(x.name)}</strong><small>${E(x.desc)}</small></span></button>`).join('')}</div><p class="demo-note">配置只影响本地原型。</p></aside><form class="glass-panel editor-pane" data-form="agent"><div class="panel-head">${icon('bot')}<h3>${E(a.name)}</h3><span class="grow"></span><span class="caption">启用</span>${toggle(a.enabled,'toggle-agent',`data-id="${a.id}" aria-label="启用子 Agent"`)}</div><div class="panel-body">${input('名称','name',a.name,'text','','required')}${input('说明','desc',a.desc)}<div class="field"><label for="agent-prompt">系统提示词</label><textarea class="field-input" id="agent-prompt" name="prompt">${E(a.prompt)}</textarea></div><div class="field-grid">${choose('默认模型','model',models.filter(m=>m.enabled).map(m=>m.name),'qwen-plus')}${input('最大执行步数','steps','50','number','','min="1" max="200"')}</div><hr class="editor-divider"><p class="editor-section-title">工具权限</p>${['网页检索','网页读取','代码执行','文件读取','图表生成','报告生成'].map(t=>`<label class="check-row"><input type="checkbox" name="tools" value="${t}" ${a.tools.includes(t)?'checked':''}>${t}</label>`).join('')}<p class="caption" style="margin-top:15px">子 Agent 仅获得此处选择的工具；原型不会执行实际任务。</p></div><div class="form-footer">${button('试运行','test-agent','play')}<span class="grow"></span><button class="button primary" type="submit">保存修改</button></div></form></div></div></section>`;}
function capabilities(){const isMcp=state.capTab==='MCP';return `<section class="page">${header('能力库','管理 MCP 服务和 Skill，为研究任务提供可调用的能力。','blocks',button(isMcp?'添加 MCP':'添加 Skill',isMcp?'new-mcp':'new-skill','plus','primary'))}<div class="content-scroll"><div class="toolbar"><div class="segmented">${['MCP','Skill'].map(t=>`<button class="${state.capTab===t?'active':''}" data-action="cap-tab" data-tab="${t}">${t}</button>`).join('')}</div><input type="search" placeholder="搜索名称或说明" aria-label="搜索能力" data-filter="cap-list"></div><div class="glass-panel table-scroll"><table><thead><tr><th>名称</th><th>${isMcp?'传输协议':'说明'}</th><th>${isMcp?'工具数量':'来源'}</th><th>状态</th><th>启用</th><th>操作</th></tr></thead><tbody>${(isMcp?connections:skills).map(c=>`<tr data-searchable="cap-list"><td><div class="dot-label"><span class="mini-icon">${icon(isMcp?'blocks':'book')}</span><div class="cell-title">${E(c.name)}<small>${E(c.desc)}</small></div></div></td><td>${E(isMcp?c.type:c.desc)}</td><td>${isMcp?c.tools+' 个':'本地 Skill'}</td><td><span class="status ${c.enabled?'success':'muted'}">${c.enabled?'可用（演示）':'已停用'}</span></td><td>${toggle(c.enabled,'toggle-cap',`data-id="${c.id}" aria-label="启用 ${E(c.name)}"`)}</td><td><div class="row-actions">${ib('settings','配置 '+c.name,'edit-cap',`data-id="${c.id}"`)}${ib('trash','删除 '+c.name,'delete-cap',`data-id="${c.id}"`)}</div></td></tr>`).join('')}</tbody></table></div><div class="notice" style="margin-top:22px">${isMcp?'MCP 的开关与连接状态在此原型中仅作交互演示，不会连接外部服务或改变项目的会话权限。':'Skill 配置为内置示例。新增条目可在当前原型中查看与启用。'}</div>${isMcp?`<section style="margin-top:30px"><h3 style="margin-bottom:15px">工具预览</h3><div class="glass-panel table-scroll"><table><thead><tr><th>工具名</th><th>所属 MCP</th><th>用途</th></tr></thead><tbody>${connections.filter(c=>c.enabled).map(c=>`<tr><td><code>mcp__${c.id===1?'search__web_search':c.id===2?'browser__read_page':'files__read_file'}</code></td><td>${E(c.name)}</td><td>${E(c.desc)}</td></tr>`).join('')||'<tr><td colspan="3">当前没有启用的 MCP。</td></tr>'}</tbody></table></div></section>`:''}</div></section>`;}
function usage(){const daily=state.usagePeriod==='近 7 天',vals=daily?[8,15,12,26,18,29,20]:[44,65,56,83,75,87,86];const names=daily?['10/11','10/12','10/13','10/14','10/15','10/16','10/17']:['1–4 日','5–8 日','9–12 日','13–16 日','17–20 日','21–25 日','26–30 日'];return `<section class="page">${header('用量统计','查看模型调用、Token 消耗与任务使用情况。','chart',button('导出数据','export-usage','download'))}<div class="content-scroll"><div class="toolbar"><div class="segmented">${['近 7 天','近 30 天'].map(t=>`<button class="${state.usagePeriod===t?'active':''}" data-action="usage-period" data-period="${t}">${t}</button>`).join('')}</div><span class="caption">全部模型 / 示例数据</span></div><div class="metrics">${[[daily?'128':'496','总调用次数','成功完成 97.7%'],[daily?'1.84M':'6.92M','Token 消耗','输入与输出合计'],[daily?'38':'142','研究任务','包括对话与 Agent 任务'],[daily?'¥ 12.68':'¥ 46.32','预估费用','仅为示例，无真实账单']].map(([v,t,n])=>`<div class="metric"><p>${t}</p><strong>${v}</strong><small>${n}</small></div>`).join('')}</div><div class="chart-layout"><div class="glass-panel"><div class="panel-head"><h3>调用趋势</h3><span class="grow"></span><span class="caption">${state.usagePeriod}</span></div><div class="panel-body"><svg class="chart" viewBox="0 0 650 240" role="img" aria-label="${state.usagePeriod}模型调用次数柱状图，演示数据">${[30,80,130,180].map((y,i)=>`<line x1="36" y1="${y}" x2="636" y2="${y}"/><text x="8" y="${y+3}">${daily?30-i*10:90-i*30}</text>`).join('')}${vals.map((v,i)=>`<rect class="bar" x="${57+i*83}" y="${180-v*(daily?5:1.67)}" width="32" height="${v*(daily?5:1.67)}" rx="4" opacity="${.42+i*.07}"/><text x="${52+i*83}" y="230">${names[i]}</text>`).join('')}</svg></div></div><div class="glass-panel"><div class="panel-head"><h3>模型用量占比</h3></div><div class="panel-body"><svg viewBox="0 0 120 120" style="display:block;max-height:120px;width:100%;margin:5px auto 25px" role="img" aria-label="qwen-plus 占比 62%，gpt-6.1-sol 占比 28%，其他占比 10%"><circle cx="60" cy="60" r="43" fill="none" stroke="var(--line)" stroke-width="13"/><circle cx="60" cy="60" r="43" fill="none" stroke="var(--accent)" stroke-width="13" stroke-dasharray="167 270" transform="rotate(-90 60 60)"/><circle cx="60" cy="60" r="43" fill="none" stroke="var(--soft)" stroke-width="13" stroke-dasharray="75 270" stroke-dashoffset="-170" transform="rotate(-90 60 60)"/><text x="60" y="65" fill="var(--text)" text-anchor="middle" font-size="20">62%</text></svg>${[['qwen-plus','62%'],['gpt-6.1-sol','28%'],['其他','10%']].map(([n,v],i)=>`<div class="legend-row"><span><i class="legend-swatch" style="opacity:${1-i*.3}"></i>${n}</span><small>${v}</small></div>`).join('')}</div></div></div><div class="section-title"><h3>模型明细</h3><span class="caption">统计数据仅用于原型展示</span></div><div class="glass-panel table-scroll"><table><thead><tr><th>模型</th><th>调用次数</th><th>输入 Token</th><th>输出 Token</th><th>预估费用</th></tr></thead><tbody>${usageRows().map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div></section>`;}
const featuredData=[{title:'AI 编程工具竞品调研',tag:'研究报告',kind:'research',desc:'从核心能力、工作流和用户反馈出发，生成可追溯的对比报告。'},{title:'第三季度销售数据分析',tag:'数据分析',kind:'sales',desc:'清洗销售数据，分析收入、产品结构与月度变化，交付交互图表。'},{title:'Java 技术资料整理',tag:'知识问答',kind:'java',desc:'将私有文档与网页资料整理为学习路线，保留原文依据。'}];
function featured(){const rows=featuredData.filter(f=>state.featureFilter==='全部'||f.tag===state.featureFilter);return `<section class="page">${header('精品对话','精选公开案例，点击查看完整回放。','star')}<div class="content-scroll"><div class="toolbar"><div class="segmented">${['全部','研究报告','数据分析','知识问答'].map(t=>`<button class="${state.featureFilter===t?'active':''}" data-action="featured-filter" data-filter-value="${t}">${t}</button>`).join('')}</div></div><div class="featured-grid">${rows.map(f=>`<article class="featured-card"><button class="featured-cover" data-action="featured-open" data-kind="${f.kind}" style="width:100%" aria-label="查看 ${f.title}"><div class="mini-report"><h4>${f.title}</h4><div class="mini-lines"></div><div class="mini-lines" style="width:60%"></div><div class="mini-chart">${[55,78,67,94,82].map(h=>`<i style="height:${h}%"></i>`).join('')}</div></div></button><div class="featured-body"><span class="tag">${f.tag}</span><h2>${f.title}</h2><p>${f.desc}</p>${button('查看完整回放','featured-open','play','',`data-kind="${f.kind}"`)}</div></article>`).join('')}</div><p class="demo-note">精选案例为原型内置内容。</p></div></section>`;}
function sop(){return `<section class="page">${header('SOP 工作区','以标准流程组织研究任务，保留每一步的输入与交付。','workflow',button('运行流程','run-sop','play','primary'))}<div class="content-scroll"><div class="split-editor"><aside class="list-pane"><h3 style="margin-bottom:15px">流程模板</h3>${[['研究报告','检索、核验、分析与报告'],['销售数据分析','清洗、统计与可视化'],['知识库整理','资料读取与结构化归纳']].map(([t,d],i)=>`<button class="selectable-row ${i===0?'active':''}" data-action="sop-template" data-index="${i}"><span class="row-icon">${icon('workflow')}</span><span><strong>${t}</strong><small>${d}</small></span></button>`).join('')}</aside><div class="glass-panel editor-pane"><div class="panel-head"><h3 id="sop-name">研究报告</h3><span class="grow"></span><span class="tag">4 个阶段</span></div><div class="panel-body"><div class="field"><label for="sop-query">研究任务</label><textarea id="sop-query" class="field-input" placeholder="输入你希望研究的问题，例如：对比三款 AI 编程工具的工作流与核心能力。"></textarea></div><div class="steps-list">${[['明确研究问题','梳理目标、边界与对比维度。'],['检索与核验','并行检索公开资料，为关键结论保留证据。'],['分析与整理','清洗数据、提炼结论，形成结构化内容。'],['生成报告','输出 HTML 报告及参考来源清单。']].map(([t,d],i)=>`<div class="workflow-step"><span class="workflow-number">${i+1}</span><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div></div><div class="form-footer"><span class="caption">在原型中模拟执行，不调用 Agent 服务。</span>${button('运行流程','run-sop','play','primary')}</div></div></div></div></section>`;}
function profile(){return `<section class="page">${header('账号设置','管理个人资料、偏好与工作区外观。','user')}<div class="content-scroll"><div class="settings-layout"><nav class="settings-nav">${['个人资料','外观偏好','安全设置'].map(t=>`<button class="${state.profileTab===t?'active':''}" data-action="profile-tab" data-tab="${t}">${t}</button>`).join('')}</nav><div>${state.profileTab==='个人资料'?`<form data-form="profile"><div class="avatar settings-avatar">${E(state.userName.slice(0,1))}</div>${input('用户名','username',state.userName,'text','','required maxlength="40"')}${input('邮箱','email','research@example.com','email','示例邮箱，仅用于视觉展示。')}<div class="field"><label for="bio">个人简介</label><textarea id="bio" name="bio" class="field-input">关注 AI 工具、开源项目与知识管理。</textarea></div><button type="submit" class="button primary">保存修改</button></form>`:state.profileTab==='外观偏好'?`<h2 style="margin-bottom:24px">外观偏好</h2><div class="field"><label>主题</label><div class="segmented"><button data-action="set-theme" data-theme="dark" class="${state.theme==='dark'?'active':''}">深色深海</button><button data-action="set-theme" data-theme="light" class="${state.theme==='light'?'active':''}">浅色浅海</button></div></div><div class="field"><label>动态背景</label>${qualityButtons()}<small>关闭动态背景后，使用静态海洋渐变；系统减少动画偏好优先。</small></div>`:`<form data-form="password"><h2 style="margin-bottom:24px">修改密码</h2>${input('当前密码','currentPassword','','password','请使用演示值，不要填写真实密码。','required minlength="8"')}${input('新密码','newPassword','','password','','required minlength="8"')}${input('确认新密码','confirmPassword','','password','','required minlength="8"')}<p class="form-error" id="password-error"></p><button type="submit" class="button primary">修改密码</button></form>`}</div></div></div></section>`;}
function login(){const reg=state.loginMode==='register';return `<div class="login-shell"><section class="login-story"><div class="login-brand"><span class="brand-monogram">R</span>Research Agent</div><div><h1>研究，<br>从问题开始。</h1><p>你的问题、资料与工作记录，<br>留在你的工作台。</p></div><footer>Research Agent / 交互原型</footer></section><section class="login-form-wrap"><form class="login-form" data-form="login"><div class="section-title"><span class="caption">你的研究工作台</span>${ib(state.theme==='dark'?'sun':'moon','切换深浅主题','theme')}</div><span class="tag">${reg?'创建账号':'账号登录'}</span><h2>${reg?'留一张研究桌。':'欢迎回来。'}</h2><p>${reg?'创建你的 Research 账号。':'登录，继续上次的研究。'}</p>${input('用户名','username','','text','','required autocomplete="username" placeholder="输入用户名"')}${input('密码','password','','password','仅演示表单流程，请勿填写真实凭据。','required minlength="8" autocomplete="off" placeholder="至少 8 个字符"')}${reg?input('确认密码','confirmPassword','','password','','required minlength="8" placeholder="再次输入密码"'):''}<div class="section-title" style="margin:0"><label class="check-row"><input type="checkbox" checked>保持登录状态</label><button class="text-link" type="button" data-action="login-help">登录帮助</button></div><p class="form-error" id="login-error" role="alert"></p><button type="submit" class="button primary">${reg?'创建账号':'进入工作台'}${icon('arrow')}</button><p class="caption" style="text-align:center">${reg?'已经有 Research 账号？':'第一次使用 Research？'} <button class="text-link" type="button" data-action="login-mode">${reg?'返回登录':'创建账号'}</button></p><div class="notice" style="margin-top:25px">独立交互原型。用户名和密码不会发送到服务器；此处不提供真实鉴权。</div></form></section></div>`;}
function qualityButtons(){return `<div class="quality-options">${[['auto','自动'],['low','低动态'],['static','静态']].map(([q,t])=>button(t,'quality','',q===state.quality?'active':'',`data-quality="${q}"`)).join('')}</div>`;}

function closePopover(){document.querySelector('.popover')?.remove();popoverAnchor=null;}
function toast(message){clearTimeout(toastTimer);$('#toast-root').innerHTML=`<div class="toast">${icon('check')}<span>${E(message)}</span></div>`;toastTimer=setTimeout(()=>$('#toast-root').replaceChildren(),3200);}
function dialog(title,body,footer='',wide=false){closePopover();dialogReturnFocus=document.activeElement;const html=`<div class="overlay-backdrop"><section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="dialog-header"><h2 id="dialog-title">${title}</h2>${ib('close','关闭弹窗','close-dialog')}</header><div class="dialog-content">${body}</div>${footer?`<footer class="dialog-footer">${footer}</footer>`:''}</section></div>`;$('#overlay-root').innerHTML=html.replaceAll('id="field-','id="dialog-field-').replaceAll('for="field-','for="dialog-field-');queueMicrotask(()=>$('.dialog input:not([type=hidden]),.dialog button,.dialog select')?.focus());}
function closeDialog(){const activeImage=$('#mask-canvas');if(activeImage)activeImage.onpointermove=null;$('#overlay-root').replaceChildren();if(dialogReturnFocus?.isConnected)dialogReturnFocus.focus();}
function confirmDialog(title,description,onConfirm){dialog(title,`<p>${E(description)}</p>`,button('取消','close-dialog')+button('确认删除','confirm-delete','trash','danger'));$('.dialog [data-action=confirm-delete]').addEventListener('click',()=>{onConfirm();closeDialog();},{once:true});}
function popover(anchor,html){closePopover();popoverAnchor=anchor;const el=document.createElement('div');el.className='popover';el.innerHTML=html;el.setAttribute('role','group');el.setAttribute('aria-label','选项');document.body.append(el);const r=anchor.getBoundingClientRect(),b=el.getBoundingClientRect();el.style.left=Math.max(10,Math.min(innerWidth-b.width-10,r.left))+'px';el.style.top=(r.bottom+b.height+9>innerHeight?Math.max(10,r.top-b.height-8):r.bottom+8)+'px';}
function popItem(label,action,ico='',attrs='',extra=''){return `<button type="button" class="menu-item" data-action="${action}" ${attrs}>${ico?icon(ico):''}<span>${label}${extra?`<small style="display:block">${extra}</small>`:''}</span></button>`;}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function setTheme(theme){state.theme=theme==='light'?'light':'dark';document.documentElement.dataset.theme=state.theme;store('ocean-prototype-theme',state.theme);window.OceanPrototype?.themeChanged();$$('[data-action=theme]').forEach(b=>{b.innerHTML=icon(state.theme==='dark'?'sun':'moon');});$$('[data-action=set-theme]').forEach(b=>b.classList.toggle('active',b.dataset.theme===state.theme));}
function setQuality(q){state.quality=q;store('ocean-prototype-quality',q);window.OceanPrototype?.setQuality(q);$$('[data-action=quality]').forEach(b=>b.classList.toggle('active',b.dataset.quality===q));}
function guide(){const engine=window.OceanPrototype?.getState();dialog('原型导航与显示',`<p>这是独立 HTML 原型，复用当前项目的导航与页面组织。所有研究结果、资料、配置和统计均为本地演示，不连接后端。选择页面可直接预览。</p><div class="page-links">${Object.entries(pageTitles).map(([v,t])=>button(t,'navigate','',v===state.view?'active':'',`data-view="${v}"`)).join('')}</div><h3 style="margin-bottom:10px">海洋主题</h3><div class="segmented" style="margin-bottom:23px"><button data-action="set-theme" data-theme="dark" class="${state.theme==='dark'?'active':''}">深色深海</button><button data-action="set-theme" data-theme="light" class="${state.theme==='light'?'active':''}">浅色浅海</button></div><h3>动态背景</h3>${qualityButtons()}<p class="caption">${engine?.fallback?'当前使用静态背景。系统减少动画偏好优先于画质选项。':'背景使用单个 Three.js WebGL 场景，桌面绘制上限 30 FPS，低动态模式 24 FPS。这里是上限设置，不是实测帧率。'}</p><div class="notice">快速体验：点击左侧历史任务查看 Agent 执行与报告；报告右边缘可拖动。聊天支持 Enter 发送、Shift + Enter 换行；Esc 关闭弹窗。</div>`,button('重置演示数据','reset-demo','refresh')+button('开始预览','close-dialog','','primary'),true);}
function render(){closePopover();document.documentElement.dataset.theme=state.theme;document.body.classList.toggle('sidebar-open',state.sidebarOpen);const views={home:welcome,chat,mrag,images,agents:agentsPage,models:modelPage,capabilities,usage,featured,sop,profile};$('#app').innerHTML=state.view==='login'?login():`<div class="shell">${sidebar()}<main class="main"><div class="mobile-bar">${ib('menu','打开导航','open-sidebar')}<strong>Research Agent</strong><span class="grow"></span>${ib('settings','原型导航与显示','guide')}</div>${(views[state.view]||welcome)()}</main></div>`;if($('#report-frame'))$('#report-frame').srcdoc=reportHTML();if(state.sidebarSearch)filterItems('sessions',state.search);document.title=`${pageTitles[state.view]||'对话'} — Research Agent 交互原型`;}
function go(view){if(!(view in pageTitles))view='home';state.view=view;state.sidebarOpen=false;state.accountOpen=false;closeDialog();render();if(location.hash.slice(1)!==view)location.hash=view;}
function openSession(id){const s=sessions.find(x=>x.id===id);if(!s)return;state.job++;state.busy=false;state.task={...s,query:s.query||s.title};state.turns=[...(s.turns||[])];state.workspace=s.kind!=='java';state.workspaceTab='preview';state.draft='';go('chat');}
function startTask(text,kind,regenerate=false){const value=String(text||'').trim();if(!value&&!state.attachments.length){toast('先输入任务，或添加附件。');return;}const query=value||`分析附件：${state.attachments.map(f=>f.name).join('、')}`;const followUp=state.view==='chat'&&Boolean(state.task);if(followUp&&!regenerate){state.turns.push({query:state.task.query||state.task.title,body:researchBody()});}if(!followUp)state.turns=[];const task=followUp?{...state.task,query,stopped:false,kind:kind||state.task.kind}:{id:++sessionSeq,title:query.slice(0,28),query,kind:kind||(/销售|CSV|收入|数据分析/i.test(query)?'sales':'research'),pinned:false};task.turns=[...state.turns];if(followUp){const i=sessions.findIndex(s=>s.id===task.id);if(i>=0)sessions[i]=task;}else sessions.unshift(task);state.task=task;state.draft='';state.attachments=[];state.workspace=false;state.busy=true;const job=++state.job;go('chat');const messages=['已拆解研究问题，正在整理演示来源…','正在对照核心维度，并生成分析结果…','正在组织报告和可视化内容…'];messages.forEach((message,i)=>setTimeout(()=>{if(state.job===job&&state.busy&&state.view==='chat'&&$('#answer-body'))$('#answer-body').innerHTML=`<p class="soft">${message}</p>`;},400+i*500));setTimeout(()=>{if(state.job!==job||!state.busy)return;state.busy=false;if(state.view==='chat')render();},2100);}
function filterItems(group,value){const needle=String(value).trim().toLowerCase();const selector=group==='sessions'?'[data-session-row]':`[data-searchable="${group}"]`;for(const el of $$(selector)){const text=group==='sessions'?el.dataset.title:el.textContent.toLowerCase();el.hidden=!text.includes(needle);}}
function newModel(){dialog('新增模型',`<form id="dialog-form" data-form="new-model">${input('模型标识','name','','text','','required placeholder="例如 qwen-plus"')}${choose('服务商预设','provider',['阿里云百炼','OpenAI 兼容'],'阿里云百炼')}${input('Base URL','url','https://dashscope.aliyuncs.com/compatible-mode/v1','url','','required')}<div class="notice">此处不需要真实 API Key。新增模型仅保存在本次原型会话中。</div></form>`,button('取消','close-dialog')+button('添加模型','dialog-save','','primary'));}
function newAgent(){dialog('新增子 Agent',`<form id="dialog-form" data-form="new-agent">${input('名称','name','','text','','required placeholder="例如 行业研究员"')}${input('说明','desc','','text','','required placeholder="描述这个 Agent 擅长的任务"')}<div class="field"><label for="new-agent-prompt">系统提示词</label><textarea id="new-agent-prompt" name="prompt" class="field-input" required placeholder="描述角色、工作方式与交付要求。"></textarea></div></form>`,button('取消','close-dialog')+button('创建子 Agent','dialog-save','','primary'));}
function editCapability(id){const isMcp=state.capTab==='MCP';const c=(isMcp?connections:skills).find(x=>x.id===id);const name=c?.name||'';dialog(c?'配置 '+E(name):isMcp?'添加 MCP':'添加 Skill',`<form id="dialog-form" data-form="capability" data-id="${id||0}">${input('名称','name',name,'text','','required')}${input('说明','desc',c?.desc||'')}${isMcp?choose('传输协议','transport',['Streamable HTTP','SSE','STDIO'],c?.type||'Streamable HTTP')+input('服务地址 / 启动命令','url',c?.url||'','text','只校验演示字段，不会建立连接或启动进程。','required'):input('Skill 路径','path','skills/example/SKILL.md','text','仅展示配置入口，不写入正式项目。')}<p class="form-error" id="capability-error"></p></form>`,button('取消','close-dialog')+button('保存','dialog-save','','primary'));}
function newKB(){dialog('创建知识库',`<form id="dialog-form" data-form="new-kb">${input('知识库名称','name','','text','','required maxlength="60" placeholder="例如 产品研究资料"')}${input('用途描述','description','','text','','placeholder="可选"')}</form>`,button('取消','close-dialog')+button('创建','dialog-save','','primary'));}
function documentPreview(index=0){const kb=selectedKB(),file=kb?.files[index];dialog(file?E(file.name):'来源摘要',`<span class="tag">${E(file?.type||'演示证据')}</span><article class="source-document"><h3>${E(file?.name||'公开产品资料')}</h3><p>${kb?.id===1?'Java 平台包含开发工具、运行环境和标准类库。Java 程序通常经过编译生成字节码，并在虚拟机上运行。':'研究资料可以帮助团队建立共同的分析口径。通过保留来源、原始内容和核验过程，让报告中的结论可以被检查。'}</p><p>此处为原型内置的示例正文，并非读取所上传文件或抓取网页的真实结果。</p></article><div class="notice">演示切片 001 / 共 ${file?.chunks||12} 个切片。正式项目的原文查看与检索契约保持不变。</div>`,button('关闭','close-dialog'));}
function askKB(){const kb=selectedKB();if(!kb){toast('请先创建或选择知识库。');return;}if(!kb.files.length){toast('请先上传文件或添加网页资料。');return;}if(!state.kbQuestion.trim()){toast('请输入问题。');return;}state.query=state.kbQuestion.trim();state.kbQuestion='';state.kbAnswer=true;render();}
function imagePreview(index){dialog('图片预览',`<div class="art-preview">${artwork(index)}</div><p class="caption">内置矢量示意图 / 仅用于确认图片预览与编辑流程。</p>`,button('下载 SVG','download-image','download','',`data-index="${index}"`)+button('编辑图片','edit-image','edit','primary',`data-index="${index}"`),true);}
function imageEditor(index){dialog('编辑图片',`<p>在图片上涂抹选区，再输入修改描述。原型支持本地涂抹，不会上传或编辑真实图片。</p><canvas id="mask-canvas" class="image-mask-canvas" width="800" height="600" aria-label="图片涂抹选区"></canvas><div class="toolbar"><label class="caption">笔刷大小 <input type="range" id="brush-size" min="8" max="80" value="28" style="width:100px;vertical-align:middle"></label>${button('清除选区','clear-mask','refresh','',`data-index="${index}"`)}</div><label class="field"><span>修改描述</span><input type="text" id="image-edit-prompt" placeholder="例如：将远处建筑改为浅色石材"></label>`,button('取消','close-dialog')+button('应用修改（演示）','apply-image-edit','','primary'),true);const canvas=$('#mask-canvas'),ctx=canvas.getContext('2d');const img=new Image();img.onload=()=>ctx.drawImage(img,0,0,800,600);img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(artwork(index));let drawing=false;const draw=e=>{if(!drawing)return;const box=canvas.getBoundingClientRect();ctx.lineWidth=Number($('#brush-size').value)*(800/box.width);ctx.strokeStyle='rgba(112,206,223,.55)';ctx.lineCap='round';ctx.lineTo((e.clientX-box.left)*800/box.width,(e.clientY-box.top)*600/box.height);ctx.stroke();};canvas.onpointerdown=e=>{drawing=true;canvas.setPointerCapture(e.pointerId);ctx.beginPath();const b=canvas.getBoundingClientRect();ctx.moveTo((e.clientX-b.left)*800/b.width,(e.clientY-b.top)*600/b.height);draw(e);};canvas.onpointermove=draw;canvas.onpointerup=()=>drawing=false;canvas.onpointercancel=()=>drawing=false;}
function modelTest(){const f=$('form[data-form=model]');if(!f?.reportValidity())return;$('#connection-result').textContent='本地字段校验通过。未建立网络连接，未验证 API Key 或模型可用性。';toast('原型字段校验通过，未发起网络请求。');}
function showFiles(){dialog('当前会话的文件',state.task?`<button type="button" class="file-artifact" data-action="open-report">${icon('code')}<span><strong>${E(taskTitle())}.html</strong><small>HTML 演示报告</small></span><span class="grow"></span>${icon('right')}</button><p class="caption">点击文件打开工作区。原型中的下载内容为本地生成的示例文件。</p>`:'<div class="empty-state">'+icon('folder')+'<h3>暂无文件</h3><p>打开一条历史任务，或发送一个研究问题，查看演示产物。</p></div>',button('关闭','close-dialog'));}
function resetDemo(){try{['ocean-prototype-theme','ocean-prototype-quality','ocean-prototype-user','ocean-prototype-kb'].forEach(k=>localStorage.removeItem(k));}catch{}location.hash='home';location.reload();}
document.addEventListener('click',event=>{
  const target=event.target.closest('[data-action]');
  if(!target){if(!event.target.closest('.popover'))closePopover();if(event.target.classList.contains('overlay-backdrop'))closeDialog();return;}
  const action=target.dataset.action,id=Number(target.dataset.id),index=Number(target.dataset.index||0);
  if(!['mode-menu','model-menu','effort-menu','session-menu','image-menu','format-menu'].includes(action))closePopover();
  switch(action){
    case 'navigate':go(target.dataset.view);break;
    case 'new-chat':state.job++;state.busy=false;state.task=null;state.turns=[];state.draft='';state.workspace=false;go('home');break;
    case 'theme':setTheme(state.theme==='dark'?'light':'dark');break;
    case 'set-theme':setTheme(target.dataset.theme);break;
    case 'quality':setQuality(target.dataset.quality);break;
    case 'guide':guide();break;
    case 'close-dialog':closeDialog();break;
    case 'dialog-save':$('.dialog form')?.requestSubmit();break;
    case 'account':state.accountOpen=!state.accountOpen;render();break;
    case 'profile':go('profile');break;
    case 'logout':dialog('退出登录','<p>退出后将展示原型登录页面，不会影响正式项目的登录状态。</p>',button('取消','close-dialog')+button('退出登录','confirm-logout','logout','primary'));break;
    case 'confirm-logout':go('login');break;
    case 'open-sidebar':state.sidebarOpen=true;document.body.classList.add('sidebar-open');break;
    case 'close-sidebar':state.sidebarOpen=false;document.body.classList.remove('sidebar-open');break;
    case 'sidebar-search':state.sidebarSearch=!state.sidebarSearch;render();$('.sidebar-search')?.focus();break;
    case 'session':openSession(id);break;
    case 'session-menu':{const s=sessions.find(x=>x.id===id);popover(target,popItem(s?.pinned?'取消置顶':'置顶任务','pin-session','pin',`data-id="${id}"`)+popItem('删除任务','delete-session','trash',`data-id="${id}"`));break;}
    case 'pin-session':{const s=sessions.find(x=>x.id===id);if(s)s.pinned=!s.pinned;render();break;}
    case 'delete-session':confirmDialog('删除任务','仅从本地原型中删除这条演示任务。',()=>{const i=sessions.findIndex(x=>x.id===id);if(i>=0)sessions.splice(i,1);if(state.task?.id===id){state.task=null;go('home');}else render();});break;
    case 'suggestion':state.draft=suggestions[index];render();$('#chat-input')?.focus();break;
    case 'send':startTask(state.draft);break;
    case 'stop':state.job++;state.busy=false;state.task.stopped=true;render();toast('已停止本地演示任务。');break;
    case 'regenerate':startTask(state.task?.query||taskTitle(),state.task?.kind,true);break;
    case 'mode-menu':popover(target,popItem('ReAct','choose-mode','brain','data-value="ReAct"','边思考边执行工具')+popItem('PlanExecute','choose-mode','search','data-value="PlanExecute"','先规划，再执行任务'));break;
    case 'choose-mode':state.mode=target.dataset.value;render();break;
    case 'data-mode':state.dataMode=!state.dataMode;render();break;
    case 'model-menu':popover(target,'<h3>模型</h3>'+models.filter(m=>m.enabled).map(m=>popItem(E(m.name),'choose-model',state.model===m.name?'check':'cpu',`data-value="${E(m.name)}"`,E(m.provider))).join('')+popItem('模型配置','navigate','settings','data-view="models"'));break;
    case 'choose-model':state.model=target.dataset.value;render();break;
    case 'effort-menu':popover(target,['low','medium','high'].map(v=>popItem(v,'choose-effort',state.effort===v?'check':'brain',`data-value="${v}"`)).join(''));break;
    case 'choose-effort':state.effort=target.dataset.value;render();break;
    case 'format-menu':popover(target,popItem('添加标题','insert-text','type','data-text="## "')+popItem('添加列表','insert-text','file','data-text="- "'));break;
    case 'insert-text':state.draft+=target.dataset.text;render();$('#chat-input')?.focus();break;
    case 'context':dialog('上下文占用','<p>此处展示上下文窗口的交互入口。原型不计算真实 Token 使用量。</p><div class="notice">模型：'+E(state.model)+'<br>演示占用：21%<br>正式项目继续使用当前的 SSE 上下文统计。</div>',button('关闭','close-dialog'));break;
    case 'attach':filePurpose='chat';$('#file-picker').click();break;
    case 'remove-attachment':state.attachments.splice(index,1);render();break;
    case 'files':showFiles();break;
    case 'open-report':if(!state.task){openSession(sessions[0]?.id);break;}state.workspace=true;state.workspaceTab='preview';if(state.view!=='chat')go('chat');else{closeDialog();render();}break;
    case 'sources':state.workspace=true;state.workspaceTab='sources';render();break;
    case 'workspace-tab':state.workspaceTab=target.dataset.tab;render();break;
    case 'close-workspace':state.workspace=false;render();break;
    case 'read-source':dialog('来源 '+(index+1),'查看与此结论关联的演示资料摘要。来源条目为虚构示例，不访问外部网站。',button('关闭','close-dialog'));break;
    case 'download-report':download(reportHTML(),'research-demo-report.html','text/html;charset=utf-8');toast('已下载 HTML 演示报告。');break;
    case 'copy-answer':navigator.clipboard?.writeText($('#answer-body')?.innerText||'').then(()=>toast('回答已复制。')).catch(()=>toast('浏览器限制复制，请选择文本手动复制。'));break;
    case 'favorite-chat':case 'feedback':target.classList.toggle('active');toast(action==='feedback'?'已记录演示反馈。':'已更新本地收藏状态。');break;
    case 'kb-toggle':state.kbOpen=!state.kbOpen;render();break;
    case 'new-kb':newKB();break;
    case 'delete-kb':confirmDialog('删除知识库','将删除本原型中的「'+(selectedKB()?.name||'知识库')+'」及其演示资料。不会修改正式项目。',()=>{knowledgeBases=knowledgeBases.filter(k=>k.id!==state.selectedKB);state.selectedKB=knowledgeBases[0]?.id??null;state.kbAnswer=false;saveKB();render();toast('演示知识库已删除。');});break;
    case 'kb-upload':filePurpose='kb';$('#file-picker').click();break;
    case 'kb-add-url':{const value=$('#kb-url')?.value.trim();if(!selectedKB()){toast('请先创建知识库。');break;}try{const u=new URL(value);if(!['http:','https:'].includes(u.protocol))throw Error();selectedKB().files.push({name:u.hostname+u.pathname,type:'网页',chunks:8});saveKB();render();toast('已添加网页演示条目，未抓取网络内容。');}catch{toast('请输入以 http:// 或 https:// 开头的有效网址。');}break;}
    case 'kb-remove-file':{const f=selectedKB()?.files[index];if(f)confirmDialog('移除资料','从演示知识库中移除「'+f.name+'」。',()=>{selectedKB().files.splice(index,1);saveKB();render();});break;}
    case 'kb-document':documentPreview(index);break;
    case 'kb-suggestion':state.kbQuestion=selectedKB()?.id===1?'什么是 Java？':'整理这份资料的关键结论';askKB();break;
    case 'ask-kb':askKB();break;
    case 'mrag-debug':dialog('检索调试','<pre class="code-view">'+E(JSON.stringify({mode:'local prototype',knowledgeBase:selectedKB()?.name||null,documents:selectedKB()?.files.length||0,retrieval:'not executed',embedding:'not called'},null,2))+'</pre>',button('关闭','close-dialog'));break;
    case 'kb-evidence':if(selectedKB()?.files.length)documentPreview(0);else toast('当前知识库还没有资料。');break;
    case 'kb-history':dialog('问答历史',`<div class="search-results">${['什么是 Java？','如何配置 Java 开发环境？'].map(q=>`<button data-action="restore-kb-question" data-question="${q}">${icon('clock')}${q}</button>`).join('')}</div><p class="demo-note">内置演示历史</p>`,button('关闭','close-dialog'));break;
    case 'restore-kb-question':state.kbQuestion=target.dataset.question;closeDialog();askKB();break;
    case 'generate-image':{const text=$('#image-prompt').value.trim();if(!text){toast('请先描述希望生成的图片。');$('#image-prompt').focus();break;}state.imagePrompt=text;const imageRatio=$('#image-ratio').value,imageStyle=$('#image-style').value;target.disabled=true;target.innerHTML='<span class="spinner"></span>生成中';setTimeout(()=>{state.imageRecords.push({index:state.imageCount,prompt:text,ratio:imageRatio,style:imageStyle});state.imageCount++;state.imageTab='我的作品';if(state.view==='images')render();toast('已生成本地示意图，未调用图像模型。');},900);break;}
    case 'image-tab':state.imageTab=target.dataset.tab;render();break;
    case 'preview-image':imagePreview(index);break;
    case 'image-menu':popover(target,popItem('预览图片','preview-image','eye',`data-index="${index}"`)+popItem('编辑图片','edit-image','edit',`data-index="${index}"`)+popItem('下载 SVG','download-image','download',`data-index="${index}"`));break;
    case 'image-attach':filePurpose='image';$('#file-picker').click();break;
    case 'image-settings':dialog('生图设置',choose('模型','imageModel',['项目默认图像模型'],'项目默认图像模型')+input('生成数量','imageAmount','1','number','','min="1" max="4"')+'<div class="notice">原型不配置或调用真实图像模型。</div>',button('保存设置','close-dialog','','primary'));break;
    case 'download-image':download(artwork(index),'ocean-prototype-image.svg','image/svg+xml');toast('已下载矢量示意图。');break;
    case 'edit-image':case 'clear-mask':imageEditor(index);break;
    case 'apply-image-edit':if(!$('#image-edit-prompt').value.trim()){toast('请输入修改描述。');$('#image-edit-prompt').focus();}else{closeDialog();toast('编辑流程演示完成，未调用图像模型。');}break;
    case 'select-model':state.selectedModel=id;render();break;
    case 'new-model':newModel();break;
    case 'toggle-model':{const m=models.find(x=>x.id===id);m.enabled=!m.enabled;render();break;}
    case 'test-model':modelTest();break;
    case 'refresh-models':render();toast('已恢复当前演示配置。');break;
    case 'model-filter':$$('[data-action=model-filter]').forEach(b=>b.classList.toggle('active',b===target));filterItems('model-list',target.dataset.filterValue);break;
    case 'select-agent':state.selectedAgent=id;render();break;
    case 'new-agent':newAgent();break;
    case 'toggle-agent':{const a=agents.find(x=>x.id===id);a.enabled=!a.enabled;render();break;}
    case 'test-agent':dialog('子 Agent 试运行',`<p>将以「${E(agents.find(a=>a.id===state.selectedAgent)?.name)}」的配置展示一次演示任务。</p>${input('任务描述','agentTestTask','','text','','placeholder="输入希望委派的任务"')}`,button('取消','close-dialog')+button('开始演示','run-agent','','primary'));break;
    case 'run-agent':{const query=$('.dialog [name=agentTestTask]')?.value;if(!query?.trim()){toast('请输入任务描述。');break;}closeDialog();startTask(query);break;}
    case 'cap-tab':state.capTab=target.dataset.tab;render();break;
    case 'new-mcp':case 'new-skill':editCapability(0);break;
    case 'edit-cap':editCapability(id);break;
    case 'toggle-cap':{const c=(state.capTab==='MCP'?connections:skills).find(c=>c.id===id);c.enabled=!c.enabled;render();break;}
    case 'delete-cap':{const list=state.capTab==='MCP'?connections:skills;const c=list.find(x=>x.id===id);confirmDialog('删除能力','从本地原型中删除「'+(c?.name||'能力')+'」。',()=>{const i=list.findIndex(x=>x.id===id);if(i>=0)list.splice(i,1);render();});break;}
    case 'usage-period':state.usagePeriod=target.dataset.period;render();break;
    case 'export-usage':download('\ufeff模型,调用次数,输入Token,输出Token,预估费用（元）\n'+usageRows().map(row=>row.map(value=>String(value).replaceAll(',','')).join(',')).join('\n'),'usage-demo.csv','text/csv;charset=utf-8');toast('已导出演示 CSV。');break;
    case 'featured-filter':state.featureFilter=target.dataset.filterValue;render();break;
    case 'featured-open':{const f=featuredData.find(f=>f.kind===target.dataset.kind);const s=sessions.find(s=>s.kind===f.kind);if(s)openSession(s.id);else startTask(f.title,f.kind);break;}
    case 'sop-template':$$('[data-action=sop-template]').forEach(b=>b.classList.toggle('active',b===target));$('#sop-name').textContent=['研究报告','销售数据分析','知识库整理'][index];break;
    case 'run-sop':{const query=$('#sop-query').value.trim();if(!query){toast('请输入研究任务。');$('#sop-query').focus();break;}state.mode='PlanExecute';startTask(query);break;}
    case 'profile-tab':state.profileTab=target.dataset.tab;render();break;
    case 'login-mode':state.loginMode=state.loginMode==='login'?'register':'login';render();break;
    case 'login-help':dialog('登录帮助','<p>正式项目请使用已有 Research 账号登录，忘记密码时联系工作区管理员。此原型可填写任意演示用户名与至少 8 位演示密码体验流程。</p>',button('关闭','close-dialog'));break;
    case 'reset-demo':resetDemo();break;
  }
});
document.addEventListener('input',event=>{const t=event.target;if(t.dataset.draft==='chat'){state.draft=t.value;const send=t.closest('[data-composer]').querySelector('.send');send.disabled=!state.busy&&!state.draft.trim()&&!state.attachments.length;t.style.height='auto';t.style.height=Math.min(150,Math.max(48,t.scrollHeight))+'px';}if(t.dataset.draft==='mrag'){state.kbQuestion=t.value;t.closest('[data-composer]').querySelector('.send').disabled=!t.value.trim();}if(t.id==='image-prompt')state.imagePrompt=t.value;if(t.dataset.filter){if(t.dataset.filter==='sessions')state.search=t.value;filterItems(t.dataset.filter,t.value);}});
document.addEventListener('change',event=>{if(event.target.dataset.change==='kb'){state.selectedKB=Number(event.target.value)||null;state.kbAnswer=false;state.kbQuestion='';render();}});
document.addEventListener('submit',event=>{
  const form=event.target;if(!form.dataset.form)return;event.preventDefault();const d=new FormData(form),get=n=>String(d.get(n)||'').trim();
  switch(form.dataset.form){
    case 'new-model':{const name=get('name');if(models.some(m=>m.name===name)){toast('已有同名演示模型，请使用其他名称。');return;}const m={id:++modelSeq,name,provider:get('provider'),url:get('url'),enabled:true,context:'131072'};models.push(m);state.selectedModel=m.id;closeDialog();go('models');toast('已添加演示模型。');break;}
    case 'model':{const m=models.find(m=>m.id===state.selectedModel);if(models.some(x=>x.id!==m.id&&x.name===get('name'))){toast('已有同名演示模型。');return;}Object.assign(m,{name:get('name'),provider:get('provider'),url:get('url'),context:get('context')});render();toast('演示配置已保存；凭据未保存。');break;}
    case 'new-agent':{const a={id:++agentSeq,name:get('name'),desc:get('desc'),prompt:get('prompt'),tools:['网页检索','网页读取'],enabled:true};agents.push(a);state.selectedAgent=a.id;closeDialog();go('agents');toast('已创建演示子 Agent。');break;}
    case 'agent':{const a=agents.find(a=>a.id===state.selectedAgent);Object.assign(a,{name:get('name'),desc:get('desc'),prompt:get('prompt'),tools:d.getAll('tools')});render();toast('子 Agent 演示配置已保存。');break;}
    case 'new-kb':{const k={id:++kbSeq,name:get('name'),desc:get('description'),files:[]};knowledgeBases.push(k);state.selectedKB=k.id;state.kbOpen=true;state.kbAnswer=false;saveKB();closeDialog();go('mrag');toast('已创建本地演示知识库。');break;}
    case 'capability':{const isMcp=state.capTab==='MCP',list=isMcp?connections:skills,id=Number(form.dataset.id);if(isMcp&&get('transport')!=='STDIO'){try{const u=new URL(get('url'));if(!['http:','https:'].includes(u.protocol))throw Error();}catch{$('#capability-error').textContent='请输入有效的 http:// 或 https:// 服务地址。';return;}}let c=list.find(c=>c.id===id);if(!c){c={id:Math.max(0,...list.map(c=>c.id))+1,enabled:true,tools:0};list.push(c);}Object.assign(c,{name:get('name'),desc:get('desc'),type:get('transport'),url:get('url')});closeDialog();render();toast('演示能力配置已保存，未建立服务连接。');break;}
    case 'profile':state.userName=get('username');store('ocean-prototype-user',state.userName);render();toast('个人资料已保存在本地原型。');break;
    case 'password':if(get('newPassword')!==get('confirmPassword')){$('#password-error').textContent='两次输入的新密码不一致。';return;}form.reset();toast('密码表单演示完成，未修改或保存真实密码。');break;
    case 'login':if(state.loginMode==='register'&&get('password')!==get('confirmPassword')){$('#login-error').textContent='两次输入的密码不一致。';return;}state.userName=get('username');store('ocean-prototype-user',state.userName);go('home');toast('已进入演示工作台，未进行真实登录。');break;
  }
});
$('#file-picker').addEventListener('change',event=>{const files=[...event.target.files];if(!files.length)return;if(filePurpose==='kb'){const kb=selectedKB();if(kb){kb.files.push(...files.map(f=>({name:f.name,type:f.name.split('.').pop().toUpperCase(),chunks:12})));saveKB();render();toast('已添加本地演示条目，未读取、上传或解析文件。');}}else if(filePurpose==='image'){toast('已选择参考图「'+files[0].name+'」，原型不上传文件。');}else{state.attachments.push(...files.map(f=>({name:f.name,size:f.size})));render();toast('已添加附件演示状态，未上传文件。');}event.target.value='';});
document.addEventListener('keydown',event=>{
  if(event.key==='Escape'){if($('.dialog'))closeDialog();else if($('.popover'))closePopover();else if(state.sidebarOpen){state.sidebarOpen=false;document.body.classList.remove('sidebar-open');}return;}
  const dlg=$('.dialog');if(event.key==='Tab'&&dlg){const focusables=$$('button:not(:disabled),input:not(:disabled),textarea,select,a[href],[tabindex="0"]',dlg).filter(e=>e.offsetParent!==null);const first=focusables[0],last=focusables.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
  if(event.target.matches('textarea[data-draft]')&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();if(event.target.dataset.draft==='mrag')askKB();else if(!state.busy)startTask(state.draft);}
  if(event.target.id==='resize-handle'&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();const pane=$('.workspace-pane'),area=$('.chat-layout');state.workspaceWidth=Math.max(310,Math.min(area.clientWidth*.7,pane.getBoundingClientRect().width+(event.key==='ArrowLeft'?20:-20)));pane.style.width=state.workspaceWidth+'px';event.target.setAttribute('aria-valuenow',state.workspaceWidth);}
});
document.addEventListener('pointerdown',event=>{if(event.target.id!=='resize-handle')return;event.preventDefault();const handle=event.target,pane=$('.workspace-pane'),area=$('.chat-layout');handle.setPointerCapture(event.pointerId);document.body.style.cursor='col-resize';handle.onpointermove=e=>{const box=area.getBoundingClientRect();state.workspaceWidth=Math.max(310,Math.min(box.width*.7,box.right-e.clientX));pane.style.width=state.workspaceWidth+'px';handle.setAttribute('aria-valuenow',Math.round(state.workspaceWidth));};const stop=()=>{handle.onpointermove=null;document.body.style.cursor='';};handle.onpointerup=stop;handle.onpointercancel=stop;});
addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(view!==state.view)go(view);});
setTheme(state.theme);setQuality(state.quality);const initial=location.hash.slice(1);state.view=initial in pageTitles?initial:'home';if(state.view==='chat')state.task={...sessions[0],query:sessions[0].title};render();
